import type { StockPhoto } from '@aglyn/aglyn/plugin-manager/stock-photo-provider'

/**
 * PIXABAY'S RECORDED ANSWERS FOR THE BETA.265 STARTS WHOSE PAGES SHIPPED WITH
 * NO PICTURE (AGL-3923): Kasvora Marketing Solutions (job BK3r4I8bF1, host
 * BVE_NlmSzm, 2026-10-18 11:32Z) and ACCA FA2 (job j4EHPke1PN, host
 * UHBPVlUZZ9, 12:05Z). What production's `stockPhotoSearches` cache held on
 * 2026-10-18, read back by each search's key (a SHA-256 of the provider and
 * the request's canonical parameters), never searched again. Ids, sizes,
 * page slugs and tags are Pixabay's own, in its order; the contributor is
 * left out.
 *
 * Kasvora searched one thing, "freelencing", which Pixabay answered with
 * nothing. The wider searches the fix makes for it (the business kind's, the
 * starter's) were never sent for any site that day, so the last two answers
 * here, which production's cache holds for OTHER sites' searches the same
 * morning, stand in for what a library answers about offices and meetings.
 */

const hit = (id: number, width: number, height: number, slug: string, tags: string): StockPhoto =>
  ({
    provider: 'pixabay',
    id: String(id),
    width,
    height,
    pageUrl: `https://pixabay.com/photos/${slug}/`,
    photographer: 'A Pixabay contributor',
    tags: tags ? tags.split(', ') : [],
    downloadUrl: `https://pixabay.com/get/g${id}_1280.jpg`,
  }) as StockPhoto

